<script setup lang="ts">
import NodeGroupPicker from "./components/NodeGroupPicker.vue";
import {usePanelContext} from "./composables/panelContext";
const {nodeGroups,loadEntitlements}=usePanelContext();
import { useApi, isCancelled } from "./lib/api";
import { latestRequest } from "./lib/requests";
const api = useApi("");
const loadRequest = latestRequest();
import { t, locale } from "./i18n";
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue';
import { Globe2, RefreshCw, RadioTower, ShieldCheck, ArrowUpRight, Download, Clock3, Plus, Pencil, Trash2, X, FileUp, Link2 } from 'lucide-vue-next';
import CountryMark from './CountryMark.vue';
import QualityTags from './QualityTags.vue';
import SpeedMetric from './SpeedMetric.vue';
import ResourceTabs from './ResourceTabs.vue';
import type { IPQuality } from './quality';
type Resource={id:string;name:string;label:string;host:string;port:number;exit:string;probe_ip:string;country:string;country_code:string;source?:string;quality?:IPQuality;node_ids?:string[];speed?:{at:number;latency_ms:number;mbps:number;bytes:number;partial:boolean;error?:string}};
type Settings={node_policy_version:number;node_rate_milli:number;node_group_ids:string[];enabled:boolean;interval_minutes:number;max_resources:number;max_latency_ms:number;min_mbps:number;candidate_limit:number;sources:string[];revision:string};
type Block={id:string;address:string;reason:string;at:number;expires_at:number;policy?:string};
type Status={skipped:number;blacklisted:number;tcp_checked:number;tcp_passed:number;download_bytes:number;duration_ms:number;running:boolean;phase:string;started_at:number;finished_at:number;next_at:number;discovered:number;checked:number;accepted:number;added:number;removed:number;rejected:number;warnings:string[];events:{at:number;address:string;reason:string}[];error?:string};
type SourceState={id:string;queued:boolean;running:boolean;last_attempt:number;last_success:number;entries:number;bytes:number;http_status:number;error:string};
type PublicSource={id:string;name:string;url?:string;address?:string;kind?:'builtin'|'url'|'text';custom?:boolean;enabled?:boolean;revision?:string};
const props=defineProps<{resources:Resource[];activeTab?:string}>();
const emit=defineEmits<{refresh:[];nodes:[];'update:activeTab':[value:string]}>();
const info=ref<{settings:Settings;status:Status;source_status:SourceState[];blacklist:{count:number;recent:Block[]};sources:PublicSource[]} | null>(null);
const form=reactive<Settings>({node_policy_version:1,node_rate_milli:1000,node_group_ids:[],enabled:false,interval_minutes:60,max_resources:3,max_latency_ms:1500,min_mbps:2,candidate_limit:80,sources:[],revision:''});
onMounted(loadEntitlements);
const publicRate=computed({get:()=>form.node_rate_milli/1000,set:(v:number)=>{form.node_rate_milli=Math.round(v*1000);form.node_policy_version=1;}});
const tab=computed({get:()=>props.activeTab||'resources',set:(value:string)=>emit('update:activeTab',value)});
const busy=ref(false),error=ref(''),saved=ref(''),qualityRunning=ref('');
const sourceModal=ref(false),sourceDelete=ref<PublicSource|null>(null),sourceError=ref(''),sourceMode=ref('url'),sourceResult=ref<{entries:number;queued:boolean;screening_pending:boolean}|null>(null);
const sourceForm=reactive({id:'',name:'',url:'',text:'',protocol:'',enabled:true,revision:''});
const phase=computed(()=>({baseline:t('检测目标校验'),recheck:t('复检已有出口'),fetch:t('获取公开列表'),screen:t('筛选可用代理'),quality:t('确认出口地区'),apply:t('同步接入节点'),idle:t('等待下次检测'),disabled:t('自动采集已关闭'),cancelled:t('任务已取消'),error:t('本轮异常')}[info.value?.status.phase || 'disabled'] || t('等待执行')));
const date=(at:number)=>at?new Date(at*1000).toLocaleString(locale.value):t('尚未执行');
const sourceGroups=computed(()=>[
  {id:'custom',name:t('自定义来源'),description:t('导入 HTTPS 列表或上传文件，候选统一进入检测队列'),sources:(info.value?.sources||[]).filter(s=>s.custom)},
  {id:'builtin',name:t('内置公开来源'),description:t('维护公开代理列表，支持按来源主动抓取'),sources:(info.value?.sources||[]).filter(s=>!s.custom)},
]);
const sourceSelectionDirty=computed(()=>JSON.stringify([...form.sources].sort())!==JSON.stringify([...(info.value?.settings.sources||[])].sort()));
const fetchableSelected=computed(()=>(info.value?.settings.sources||[]).filter(id=>info.value?.sources.some(s=>s.id===id&&s.kind!=='text'&&(!s.custom||s.enabled))));
async function load(reset=false){
 const request=loadRequest.start();
 try {
  const result=await api('/public-pool','GET',undefined,{signal:request.signal});
  if(!loadRequest.isCurrent(request))return;
  info.value=result;error.value='';
  if(reset&&info.value)Object.assign(form,info.value.settings,{sources:[...info.value.settings.sources]});
 }catch(e){if(loadRequest.isCurrent(request)&&!isCancelled(e))error.value=(e as Error).message;}
}
function syncSourceSettings(){if(info.value)Object.assign(form,{sources:[...info.value.settings.sources],revision:info.value.settings.revision,enabled:info.value.settings.enabled});}
async function save(enabled=form.enabled){if(busy.value)return;busy.value=true;error.value='';saved.value='';try{await api('/public-pool','PUT',{...form,sources:[...(info.value?.settings.sources||[])],enabled});await load(true);emit('refresh');saved.value=enabled?t('策略已保存，正在采集与检测'):t('已关闭，自动节点和公共资源已撤下');}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}finally{busy.value=false;}}
async function toggleCollection(){if(busy.value||!info.value)return;busy.value=true;error.value='';saved.value='';try{const enabled=!info.value.settings.enabled;await api('/public-pool','PUT',{...info.value.settings,enabled});await load();syncSourceSettings();emit('refresh');saved.value=enabled?t('策略已保存，正在采集与检测'):t('已关闭，自动节点和公共资源已撤下');}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}finally{busy.value=false;}}
async function saveSourceSelection(){if(busy.value||!info.value)return;busy.value=true;error.value='';saved.value='';try{await api('/public-pool','PUT',{...info.value.settings,sources:[...form.sources]});await load();syncSourceSettings();saved.value=t('采集来源已保存');}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}finally{busy.value=false;}}
async function run(){if(busy.value)return;busy.value=true;error.value='';try{await api('/public-pool/run','POST',{});await load();}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}finally{busy.value=false;}}
async function quality(p:Resource){if(qualityRunning.value)return;qualityRunning.value=p.id;error.value='';try{await api('/ips/'+p.id+'/quality','POST',{});emit('refresh');}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}finally{qualityRunning.value='';}}
const sourceState=(id:string)=>info.value?.source_status?.find(s=>s.id===id);
const sourcePending=computed(()=>info.value?.source_status?.some(s=>s.queued||s.running)||false);
async function fetchSources(ids:string[]){if(busy.value)return;busy.value=true;error.value='';saved.value='';try{await api('/public-pool/sources/fetch','POST',{ids});await load();saved.value=t('来源抓取已排队，完成后按现有策略检测入池');}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function editSource(source?:PublicSource){Object.assign(sourceForm,{id:source?.id||'',name:source?.name||'',url:'',text:'',protocol:'',enabled:source?.enabled??true,revision:source?.revision||''});sourceMode.value='url';sourceError.value='';sourceModal.value=true;}
function closeSource(){if(busy.value)return;sourceModal.value=false;sourceDelete.value=null;sourceForm.url='';sourceForm.text='';sourceError.value='';}
async function readSourceFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>1048576)throw new Error(t('文件不能超过 1 MiB'));sourceForm.text=await file.text();sourceMode.value='text';sourceError.value='';}catch(e){sourceError.value=(e as Error).message;}finally{input.value='';}}
async function saveCustomSource(){if(busy.value)return;busy.value=true;sourceError.value='';try{
 const result=await api('/public-pool/sources'+(sourceForm.id?'/'+sourceForm.id:''),sourceForm.id?'PUT':'POST',sourceForm.id?{name:sourceForm.name,enabled:sourceForm.enabled,revision:sourceForm.revision}:{name:sourceForm.name,enabled:sourceForm.enabled,protocol:sourceForm.protocol,...(sourceMode.value==='url'?{url:sourceForm.url}:{text:sourceForm.text})});
 if(!sourceForm.id)sourceResult.value={entries:result.entries||0,queued:result.queued,screening_pending:result.screening_pending};
 sourceModal.value=false;sourceForm.url='';sourceForm.text='';await load();syncSourceSettings();saved.value=t('公开来源已保存');
}catch(e){sourceError.value=(e as Error).message;}finally{busy.value=false;}}
async function removeSource(){if(busy.value||!sourceDelete.value)return;busy.value=true;sourceError.value='';try{await api('/public-pool/sources/'+sourceDelete.value.id+'?revision='+encodeURIComponent(sourceDelete.value.revision||''),'DELETE');sourceDelete.value=null;await load();syncSourceSettings();emit('refresh');saved.value=t('公开来源已删除，已验证出口保留');}catch(e){sourceError.value=(e as Error).message;}finally{busy.value=false;}}
let timer:ReturnType<typeof setTimeout>|undefined;let mounted=true;
async function poll(){if(!document.hidden&&!busy.value)await load();if(mounted)timer=setTimeout(poll,info.value?.status.running||sourcePending.value?3000:30000);}
onMounted(async()=>{await load(true);if(mounted)timer=setTimeout(poll,3000)});onUnmounted(()=>{mounted=false;loadRequest.cancel();clearTimeout(timer)});
</script>

<template>
  <section class="public-pool-page">
    <div class="page-heading public-page-heading"><div><h1>{{t('公共 IP 池')}}</h1><p class="resource-page-description">{{t('集中管理公开来源、合格出口与自动筛选')}}</p></div><button role="switch" :aria-checked="info?.settings.enabled || false" :aria-label="t('自动采集公共代理')" :class="['public-switch',{on:info?.settings.enabled}]" :disabled="busy || !info" @click="toggleCollection"><i/><span>{{ !info ? t('读取策略…') : info.settings.enabled ? t('自动采集已开启') : t('自动采集已关闭') }}</span></button></div>
    <p v-if="error" class="public-error" role="alert">{{t(error)}}</p><p v-if="saved" class="public-success" role="status">{{t(saved)}}</p>
    <div class="public-metrics"><article><span>{{t('可用公共出口')}}</span><strong>{{resources.length}}<small>/ {{info?.settings.max_resources || 3}}</small></strong></article><article><span>{{t('自动接入节点')}}</span><strong>{{resources.reduce((sum,p)=>sum+(p.node_ids?.length||0),0)}}</strong></article><article><span>{{t('采集来源')}}</span><strong>{{info?.settings.sources.length||0}}<small>/ {{info?.sources.length||0}}</small></strong></article><article><span>{{t('下次计划检测')}}</span><strong class="public-time">{{info?.settings.enabled ? info.status.running ? t('正在执行') : date(info.status.next_at) : t('未启用')}}</strong></article></div>
    <ResourceTabs id="public-pool" v-model="tab" :label="t('公共 IP 池分类')" :items="[{id:'resources',label:t('可用出口'),count:resources.length},{id:'sources',label:t('来源管理'),...(info?{count:info.sources.length}:{})},{id:'policy',label:t('策略与记录')}]"/>
    <div id="public-pool-panel" role="tabpanel" :aria-labelledby="'public-pool-tab-'+tab">
    <template v-if="tab==='resources'">
    <div class="public-resources-head"><div><h2>{{ t("可用出口") }}<span class="count">{{resources.length}}</span></h2><p>{{ t("独立管理，仅显示通过筛选的公开代理") }}</p></div><button class="text-button" @click="emit('nodes')"><RadioTower :size="15"/>{{ t("查看自动节点") }}</button></div>
    <div class="public-resource-grid"><article v-for="p in resources" :key="p.id" class="public-resource"><header><CountryMark :code="p.country_code" :country="p.country"/><div><strong>{{p.probe_ip}}</strong><small>{{p.country || t('国家待识别')}}</small></div><span class="badge neutral">{{p.exit.toUpperCase()}}</span></header><QualityTags :value="p.quality" :name="p.name" :running="qualityRunning===p.id" @run="quality(p)"/><div class="public-resource-speed"><SpeedMetric :result="p.speed" :running="false"/><span>{{p.node_ids?.length || 0}}{{ t("个自动节点") }}</span></div><footer><span>{{info?.sources.find(s=>s.id===p.source)?.name || p.source}}</span><small>{{p.host}}:{{p.port}}</small></footer></article><div v-if="!resources.length" class="public-empty"><Globe2 :size="32"/><h3>{{info?.status.running ? t('正在寻找合格出口') : t('等待合格的公共代理')}}</h3><p>{{ t("通过 HTTPS 连通、延迟与下载检测后，资源和两种接入节点会自动出现。") }}</p><button @click="tab='sources'"><Download :size="14"/>{{t("管理与导入来源")}}</button></div></div>
    </template>
    <section v-else-if="tab==='sources'" class="public-source-manager" :aria-label="t('公开来源管理')">
      <header><div><h2>{{t('公开来源管理')}}</h2><p>{{t('主动获取最新候选列表，验证合格后才生成公共节点')}}</p></div><div class="public-module-actions"><button :disabled="busy||!fetchableSelected.length||sourcePending" @click="fetchSources(fetchableSelected)"><Download :size="15"/>{{t('抓取已启用来源')}}</button><button class="primary" :disabled="busy||!info" @click="editSource()"><Plus :size="15"/>{{t('导入公开来源')}}</button></div></header>
      <div class="public-source-selection"><span><ShieldCheck :size="15"/>{{t('仅勾选的来源参与自动采集')}}</span><button :disabled="busy||!info||!sourceSelectionDirty" @click="saveSourceSelection">{{t('保存来源选择')}}</button></div>
      <div v-if="sourceResult" class="public-import-result" role="status"><div><strong>{{sourceResult.queued?t('来源已进入抓取队列'):t('候选列表已导入')}}</strong><p>{{sourceResult.queued?t('抓取完成后将显示候选数量'):t('候选地址')+' · '+sourceResult.entries}} · {{sourceResult.screening_pending?t('等待按当前策略筛选'):t('开启自动采集后进行筛选')}}</p></div><button class="icon" :aria-label="t('关闭导入结果')" @click="sourceResult=null"><X :size="15"/></button></div>
      <p v-if="!info" class="public-footnote" role="status">{{t('正在读取公开来源…')}}</p>
      <section v-for="group in sourceGroups" :key="group.id" class="public-source-group" :aria-label="group.name">
        <div class="public-group-heading"><div><h3>{{group.name}}<span class="count">{{group.sources.length}}</span></h3><p>{{group.description}}</p></div><span v-if="group.id==='custom'" class="badge neutral">{{t('链接 / 粘贴 / 文件')}}</span></div>
        <div class="public-source-grid">
          <article v-for="s in group.sources" :key="s.id">
            <header><label><input v-model="form.sources" type="checkbox" :value="s.id" :disabled="busy||s.custom&&!s.enabled" :aria-label="t('自动采集来源 ')+t(s.name)"/><strong>{{t(s.name)}}</strong></label><a v-if="!s.custom&&s.url" :href="s.url" target="_blank" rel="noreferrer" :aria-label="t('查看来源 ')+t(s.name)"><ArrowUpRight :size="14"/></a><span v-else class="public-source-kind">{{s.kind==='text'?t('导入列表'):t('HTTPS 来源')}}</span></header>
            <p v-if="s.address" class="public-source-address">{{s.address}}</p>
            <div class="public-source-state"><span :class="['badge',sourceState(s.id)?.error?'danger':sourceState(s.id)?.queued||sourceState(s.id)?.running?'neutral':sourceState(s.id)?.last_success?'success':'neutral']">{{s.custom&&!s.enabled?t('已暂停'):sourceState(s.id)?.running?t('抓取中'):sourceState(s.id)?.queued?t('排队中'):sourceState(s.id)?.error?t('抓取失败'):sourceState(s.id)?.last_success?t('已获取列表'):t('尚未抓取')}}</span><span><b>{{sourceState(s.id)?.last_success?sourceState(s.id)?.entries:'—'}}</b> {{t('候选地址')}}</span></div>
            <p class="public-source-time"><Clock3 :size="12"/>{{t('最近成功')}} · {{date(sourceState(s.id)?.last_success||0)}}</p><p v-if="sourceState(s.id)?.error" class="public-warning">{{t(sourceState(s.id)?.error||'')}}</p>
            <footer><small>{{sourceState(s.id)?.bytes?((sourceState(s.id)?.bytes||0)/1024).toFixed(1)+' KiB':t('列表大小待确认')}}<span v-if="sourceState(s.id)?.http_status===304"> · {{t('来源未变更')}}</span></small><div class="public-source-actions"><button v-if="s.custom" class="icon" :aria-label="t('编辑公开来源 ')+s.name" :disabled="busy" @click="editSource(s)"><Pencil :size="13"/></button><button v-if="s.custom" class="icon danger-button" :aria-label="t('删除公开来源 ')+s.name" :disabled="busy" @click="sourceError='';sourceDelete=s"><Trash2 :size="13"/></button><button v-if="s.kind!=='text'" :disabled="busy||sourceState(s.id)?.queued||sourceState(s.id)?.running" :aria-label="t('抓取来源 ')+t(s.name)" @click="fetchSources([s.id])"><RefreshCw :size="13" :class="{spin:sourceState(s.id)?.running}"/>{{t('立即抓取')}}</button><span v-else class="public-source-kind">{{t('手动导入')}}</span></div></footer>
          </article>
          <button v-if="group.id==='custom'&&!group.sources.length" class="public-add-source" :disabled="busy||!info" @click="editSource()"><Plus :size="21"/><strong>{{t('导入第一个公开来源')}}</strong><span>{{t('HTTPS 链接、代理列表或本地文件')}}</span></button>
        </div>
      </section>
      <details class="public-source-rules"><summary>{{t('采集与导入规则')}}</summary><p>{{t('手动抓取串行执行，任务至少间隔 15 秒，同一来源至少间隔 60 秒。黑名单继续生效；关闭自动采集时仅更新候选列表。')}}</p><p>{{t('最多 16 个自定义来源，每个列表最多 1 MiB、2000 个候选。导入记录不等于可用出口，必须通过连通与性能筛选。')}}</p></details>
    </section>
    <template v-else>
      <div class="public-efficiency"><span>{{t('黑名单')}}<strong>{{info?.blacklist.count||0}}</strong></span><span>{{t('本轮跳过')}}<strong>{{info?.status.skipped||0}}</strong></span><span>{{t('TCP 可达')}}<strong>{{info?.status.tcp_passed||0}} / {{info?.status.tcp_checked||0}}</strong></span><span>{{t('已读下载样本')}}<strong>{{((info?.status.download_bytes||0)/1048576).toFixed(2)}} MiB</strong></span></div>
    <div class="public-config-grid"><form class="public-policy" @submit.prevent="save()"><div class="section-head"><div><h2>{{ t("筛选策略") }}</h2><p>{{ t("设置性能底线与采集频率") }}</p></div><ShieldCheck :size="18"/></div><div class="public-fields"><label>{{ t("检测间隔 · 分钟") }}<input v-model.number="form.interval_minutes" type="number" min="10" max="1440" required :aria-label="t('公共代理检测间隔')"/></label><label>{{ t("保留出口 · 个") }}<input v-model.number="form.max_resources" type="number" min="1" max="5" required :aria-label="t('公共代理保留数量')"/></label><label>{{ t("延迟上限 · ms") }}<input v-model.number="form.max_latency_ms" type="number" min="100" max="10000" required :aria-label="t('公共代理延迟上限')"/></label><label>{{ t("下载下限 · Mbps") }}<input v-model.number="form.min_mbps" type="number" min="0.1" max="1000" step="0.1" required :aria-label="t('公共代理下载下限')"/></label><label>{{ t("每轮候选上限") }}<input v-model.number="form.candidate_limit" type="number" min="4" max="200" required :aria-label="t('公共代理每轮候选上限')"/></label></div><div class="public-node-policy"><label>{{t("公共节点默认倍率")}}<input v-model.number="publicRate" type="number" min="0" max="100" step="0.01" required/></label><NodeGroupPicker v-model="form.node_group_ids" :groups="nodeGroups" scope="public"/><p class="field-help">{{t("自动节点继承此处的倍率与分组；下一次维护时统一应用。")}}</p></div><p class="source-selection-note">{{t('采集来源在来源管理中单独选择和保存。')}}</p><footer><p>{{ t("每个出口自动创建 2 个节点。关闭时撤下自动节点并清空公共池。不通立即拉黑 24 小时；性能不达标跳过 1 小时并撤下节点。") }}</p><button class="primary" :disabled="busy || !info" type="submit">{{ t("保存策略") }}</button></footer></form>
      <aside class="public-run"><div class="section-head"><h2>{{ t("运行记录") }}</h2><button class="text-button" :disabled="busy || !info?.settings.enabled || info?.status.running" @click="run"><RefreshCw :size="14" :class="{spin:info?.status.running}"/>{{ t("立即检测") }}</button></div><div class="public-phase"><i :class="['dot',{warning:info?.status.error}]"/><strong>{{t(phase)}}</strong></div><dl><div><dt>{{ t("上次完成") }}</dt><dd>{{date(info?.status.finished_at || 0)}}</dd></div><div><dt>{{ t("列表候选") }}</dt><dd>{{info?.status.discovered || 0}}{{ t("个") }}</dd></div><div><dt>{{ t("本轮新增") }}</dt><dd>{{info?.status.added || 0}}{{ t("个出口") }}</dd></div><div><dt>{{ t("不达标") }}</dt><dd>{{info?.status.rejected || 0}}{{ t("个") }}</dd></div><div><dt>{{ t("本轮耗时") }}</dt><dd>{{info?.status.duration_ms ? (info.status.duration_ms/1000).toFixed(1)+t(' 秒') : t('进行中 / 待执行')}}</dd></div></dl><p v-if="info?.status.error" class="public-error">{{t(info.status.error)}}</p><p v-for="w in info?.status.warnings" :key="w" class="public-warning">{{t(w)}}</p><div class="public-events"><article v-for="(e,i) in [...(info?.status.events || [])].reverse()" :key="i"><span>{{e.address}}</span><small>{{t(e.reason)}}</small></article><p v-if="!info?.status.events?.length">{{ t("开启后将在这里显示筛选与淘汰记录。") }}</p></div></aside></div>
    <section class="public-blacklist"><div class="section-head"><div><h2>{{ t("检测黑名单") }}<span class="count">{{info?.blacklist.count || 0}}</span></h2><p>{{ t("跨来源去重，冷却期内直接跳过。到期再评估；更改性能阈值会重新评估性能类记录。") }}</p></div><ShieldCheck :size="18"/></div><div class="public-block-list"><article v-for="b in info?.blacklist.recent" :key="b.id"><strong>{{b.address}}</strong><span>{{t(b.reason)}}</span><small>{{date(b.expires_at)}}{{ t("后可重测") }}</small></article><p v-if="!info?.blacklist.recent.length">{{ t("尚无黑名单记录，不通的代理将在这里自动记录。") }}</p></div><p class="public-footnote">{{ t("显示最近 12 项，最多保留 8192 项。黑名单保存在服务器，重启和开关不会清空。") }}</p></section>
    <p class="public-footnote">{{ t("8 路 TCP 预筛 · 最多 2 路 HTTPS 检测 · 公开列表缓存 15 分钟。延迟不达标立即停止下载；每个下载样本 256 KiB，每轮采集测速最多读取 4 MiB。检测从 VPS 发起，IP 校验支持 ipify / Cloudflare / AWS，下载目标为当轮可用的 Cloudflare 或 OVH。流媒体质量在后台逐项补充，短时样本不代表持续带宽。") }}</p>
    </template>
    </div>
    <Teleport to="body"><div v-if="sourceModal||sourceDelete" class="message-overlay" @click.self="closeSource">
      <form v-if="sourceModal" class="compose-card public-source-dialog" role="dialog" aria-modal="true" :aria-label="t(sourceForm.id?'编辑公开来源':'导入公开来源')" @submit.prevent="saveCustomSource">
        <header><h2>{{t(sourceForm.id?'编辑公开来源':'导入公开来源')}}</h2><button class="icon" type="button" :aria-label="t('关闭')" :disabled="busy" @click="closeSource"><X :size="20"/></button></header>
        <p v-if="sourceError" class="error" role="alert">{{t(sourceError)}}</p>
        <label>{{t('来源名称')}}<input v-model="sourceForm.name" maxlength="80" required :placeholder="t('例如：备用公开代理列表')"/></label>
        <template v-if="!sourceForm.id">
          <div class="public-import-modes"><button type="button" :class="{active:sourceMode==='url'}" @click="sourceMode='url'"><Link2 :size="14"/>{{t('HTTPS 链接')}}</button><button type="button" :class="{active:sourceMode==='text'}" @click="sourceMode='text'"><Download :size="14"/>{{t('粘贴列表')}}</button><label class="import-file-button"><FileUp :size="14"/>{{t('导入文件')}}<input type="file" accept=".txt,.csv,.list,text/plain,text/csv" @change="readSourceFile"/></label></div>
          <label v-if="sourceMode==='url'">{{t('公开代理列表链接')}}<input v-model="sourceForm.url" type="password" required autocomplete="off" maxlength="8192" placeholder="https://…"/><span class="field-caption">{{t('链接加密保存，页面只展示来源域名')}}</span></label>
          <label v-else>{{t('公开代理列表')}}<textarea v-model="sourceForm.text" rows="7" maxlength="1048576" required placeholder="http://203.0.113.1:8080&#10;socks5://203.0.113.2:1080"/><span class="field-caption">{{t('每行一个 HTTP / SOCKS5 代理，最多 2000 项')}}</span></label>
          <label>{{t('无协议地址的默认类型')}}<select v-model="sourceForm.protocol"><option value="">{{t('根据链接协议识别')}}</option><option value="http">HTTP CONNECT</option><option value="socks5">SOCKS5</option></select><span class="field-caption">{{t('列表包含 IP:端口 时请选择默认类型')}}</span></label>
        </template>
        <label class="public-source-enabled"><input v-model="sourceForm.enabled" type="checkbox"/>{{t('参与自动采集')}}</label>
        <p class="public-import-note">{{t('导入后先保存为候选来源；自动采集开启时按当前筛选策略检测，通过后才创建公共出口与节点。')}}</p>
        <footer><button type="button" :disabled="busy" @click="closeSource">{{t('取消')}}</button><button class="primary" :disabled="busy"><RefreshCw v-if="busy" :size="14" class="spin"/>{{t(sourceForm.id?'保存':'导入公开来源')}}</button></footer>
      </form>
      <section v-else-if="sourceDelete" class="compose-card" role="dialog" aria-modal="true" :aria-label="t('删除公开来源')"><h2>{{t('删除公开来源')}} · {{sourceDelete.name}}</h2><p class="public-import-note">{{t('删除来源及其候选缓存，停止后续抓取。已通过检测的出口和节点保留，仍会接受定期复检。')}}</p><p v-if="sourceError" class="error" role="alert">{{t(sourceError)}}</p><footer><button :disabled="busy" @click="closeSource">{{t('取消')}}</button><button class="danger-button" :disabled="busy" @click="removeSource">{{t('删除公开来源')}}</button></footer></section>
    </div></Teleport>
  </section>
</template>
<style>
