x;flex-direction:column;gap:12px;margin:24px 0;font-size:12px}.public-sources>span{color:var(--muted,#93a4ba);font-size:11px}.public-sources label{display:flex;flex-direction:row;align-items:center;gap:10px;text-align:left}.public-sources input{width:14px;height:14px}.public-sources a{color:var(--muted,#93a4ba);margin-left:auto}.public-policy footer{border-top:1px solid var(--border,#29394d);padding-top:14px;display:flex;flex-direction:column;align-items:flex-end;gap:12px}.public-policy footer p{margin:0;font-size:11px}.public-phase{display:flex;align-items:center;gap:8px;color:#32b7a4;font-size:14px;padding:14px;border-radius:8px;background:#14988d13}.public-run dl{display:flex;flex-direction:column;gap:14px;margin:22px 0}.public-run dl div{display:flex;justify-content:space-between;gap:16px;font-size:12px}.public-run dt{color:var(--muted,#93a4ba)}.public-run dd{margin:0;text-align:right}.public-events{max-height:225px;overflow:auto;border-top:1px solid var(--border,#29394d)}.public-events article{display:flex;flex-direction:column;gap:6px;padding:11px 0;border-bottom:1px solid var(--border,#29394d);font-size:11px}.public-events small{color:var(--muted,#93a4ba);font-size:11px}.public-error{color:#ed8593!important;background:#e5586515;padding:12px;border-radius:6px}.public-success{color:#2cbaa6!important}.public-warning{color:#deb775!important}.public-resources-head{display:flex;justify-content:space-between;gap:16px;align-items:center;margin:30px 0 20px}.public-resources-head h2{margin:0}.public-resources-head p{margin:7px 0 0}.public-resource-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.public-resource{padding:20px;border:1px solid var(--border,#29394d);border-radius:10px;background:var(--surface)}.public-resource header{display:flex;align-items:center;gap:11px;margin-bottom:12px}.public-resource header>div{display:flex;flex-direction:column;gap:5px}.public-resource header .badge{margin-left:auto}.public-resource header small,.public-resource footer{color:var(--muted,#93a4ba);font-size:11px}.public-resource-speed{display:flex;justify-content:space-between;gap:12px;align-items:center;margin:20px 0}.public-resource-speed>span{font-size:11px;color:var(--muted,#93a4ba)}.public-resource footer{padding-top:12px;border-top:1px solid var(--border,#29394d);display:flex;flex-direction:column;gap:6px}.public-empty{grid-column:1/-1;display:flex;align-items:center;flex-direction:column;padding:44px 24px;border:1px dashed var(--border,#29394d);border-radius:10px;text-align:center;color:var(--muted,#93a4ba)}.public-empty h3{font-size:15px;margin:17px 0 3px}.public-footnote{margin:20px 0!important;font-size:11px!important}[data-theme=light] .public-hero,[data-theme=light] .public-metrics article,[data-theme=light] .public-policy,[data-theme=light] .public-run,[data-theme=light] .public-resource{background:#fff}@media(max-width:1100px){.public-resource-grid{grid-template-columns:1fr 1fr}.public-config-grid{grid-template-columns:1fr}}@media(max-width:650px){.public-hero{padding:20px;gap:12px;flex-wrap:wrap}.public-hero-icon{display:none}.public-hero h2{font-size:18px}.public-hero .spacer{display:none}.public-switch{margin-top:8px}.public-metrics{grid-template-columns:1fr 1fr;gap:12px}.public-metrics article{padding:16px}.public-policy,.public-run{padding:20px}.public-resource-grid{grid-template-columns:1fr}.public-resources-head{align-items:flex-start;flex-direction:column}.public-fields{gap:13px}}

